package offline;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/** Set of disjoint, merged, half open [start,end) intervals. */
public final class IntervalSet {

    private final TreeMap<Long, Long> intervals = new TreeMap<>();

    public IntervalSet copy() {
        IntervalSet other = new IntervalSet();
        other.intervals.putAll(intervals);
        return other;
    }

    public void restore(IntervalSet snapshot) {
        intervals.clear();
        intervals.putAll(snapshot.intervals);
    }

    public boolean isEmpty() {
        return intervals.isEmpty();
    }

    /** Adds [start,end) and merges it with touching or overlapping intervals. */
    public void add(long start, long end) {
        if (start >= end) {
            return;
        }
        long newStart = start;
        long newEnd = end;
        Map.Entry<Long, Long> before = intervals.floorEntry(start);
        if (before != null && before.getValue() >= start) {
            newStart = before.getKey();
            newEnd = Math.max(newEnd, before.getValue());
            intervals.remove(before.getKey());
        }
        while (true) {
            Map.Entry<Long, Long> next = intervals.ceilingEntry(newStart);
            if (next == null || next.getKey() > newEnd) {
                break;
            }
            newEnd = Math.max(newEnd, next.getValue());
            intervals.remove(next.getKey());
        }
        intervals.put(newStart, newEnd);
    }

    public long count() {
        long total = 0;
        for (long[] interval : list()) {
            total += interval[1] - interval[0];
        }
        return total;
    }

    public int intervalCount() {
        return intervals.size();
    }

    /** Length of the contiguous acknowledged prefix starting at zero. */
    public long prefix() {
        Map.Entry<Long, Long> first = intervals.firstEntry();
        if (first == null || first.getKey() != 0L) {
            return 0;
        }
        return first.getValue();
    }

    public List<long[]> list() {
        List<long[]> result = new ArrayList<>(intervals.size());
        for (Map.Entry<Long, Long> entry : intervals.entrySet()) {
            result.add(new long[] {entry.getKey(), entry.getValue()});
        }
        return result;
    }
}
