package offline;

import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.BitSet;
import java.util.List;
import java.util.TreeMap;

/** Sparse byte storage used for stream payloads and CRYPTO data. */
public final class ByteStore {

    static final int CHUNK_BITS = 10;
    static final int CHUNK_SIZE = 1 << CHUNK_BITS;
    static final int CHUNK_MASK = CHUNK_SIZE - 1;

    static final class Chunk {
        final byte[] data = new byte[CHUNK_SIZE];
        final BitSet present = new BitSet(CHUNK_SIZE);

        Chunk copy() {
            Chunk other = new Chunk();
            System.arraycopy(data, 0, other.data, 0, CHUNK_SIZE);
            other.present.or(present);
            return other;
        }

        void restore(Chunk source) {
            System.arraycopy(source.data, 0, data, 0, CHUNK_SIZE);
            present.clear();
            present.or(source.present);
        }
    }

    private final TreeMap<Long, Chunk> chunks = new TreeMap<>();

    Chunk chunk(long index) {
        return chunks.get(index);
    }

    void restoreChunk(long index, Chunk snapshot) {
        Chunk current = chunks.get(index);
        if (current == null) {
            chunks.put(index, snapshot.copy());
        } else {
            current.restore(snapshot);
        }
    }

    public boolean contains(long offset) {
        Chunk chunk = chunks.get(offset >>> CHUNK_BITS);
        return chunk != null && chunk.present.get((int) (offset & CHUNK_MASK));
    }

    public byte get(long offset) {
        Chunk chunk = chunks.get(offset >>> CHUNK_MASK == 0 ? 0 : offset >>> CHUNK_BITS);
        return chunk == null ? 0 : chunk.data[(int) (offset & CHUNK_MASK)];
    }

    /**
     * Stores {@code source} at {@code offset}.
     *
     * @return false when an already stored byte differs from the new one
     */
    public boolean store(long offset, byte[] source, Journal journal) {
        for (int i = 0; i < source.length; i++) {
            long position = offset + i;
            Chunk chunk = chunks.get(position >>> CHUNK_BITS);
            if (chunk != null) {
                int index = (int) (position & CHUNK_MASK);
                if (chunk.present.get(index) && chunk.data[index] != source[i]) {
                    return false;
                }
            }
        }
        for (int i = 0; i < source.length; i++) {
            long position = offset + i;
            long chunkIndex = position >>> CHUNK_BITS;
            Chunk chunk = chunks.get(chunkIndex);
            if (chunk == null) {
                chunk = new Chunk();
                chunks.put(chunkIndex, chunk);
            } else {
                journal.snapshotChunk(this, chunkIndex, chunk.copy());
            }
            int index = (int) (position & CHUNK_MASK);
            chunk.data[index] = source[i];
            chunk.present.set(index);
        }
        return true;
    }

    /** Number of stored bytes. */
    public long unique() {
        long total = 0;
        for (Chunk chunk : chunks.values()) {
            total += chunk.present.cardinality();
        }
        return total;
    }

    /** Sorted, merged, half open ranges of stored bytes. */
    public List<long[]> ranges() {
        List<long[]> result = new ArrayList<>();
        long[] pending = null;
        for (java.util.Map.Entry<Long, Chunk> entry : chunks.entrySet()) {
            long base = entry.getKey() << CHUNK_BITS;
            Chunk chunk = entry.getValue();
            int index = chunk.present.nextSetBit(0);
            while (index >= 0) {
                int end = chunk.present.nextClearBit(index);
                long start = base + index;
                long stop = base + end;
                if (pending != null && pending[1] == start) {
                    pending[1] = stop;
                } else {
                    if (pending != null) {
                        result.add(pending);
                    }
                    pending = new long[] {start, stop};
                }
                index = chunk.present.nextSetBit(end);
            }
        }
        if (pending != null) {
            result.add(pending);
        }
        return result;
    }

    /** Length of the contiguous stored prefix starting at zero. */
    public long prefix() {
        long length = 0;
        long chunkIndex = 0;
        while (true) {
            Chunk chunk = chunks.get(chunkIndex);
            if (chunk == null) {
                break;
            }
            int index = chunk.present.nextSetBit(0);
            if (index != 0) {
                break;
            }
            int end = chunk.present.nextClearBit(0);
            if (end == CHUNK_SIZE) {
                length += CHUNK_SIZE;
                chunkIndex++;
                continue;
            }
            length += end;
            break;
        }
        return length;
    }

    /** Feeds the contiguous stored prefix into {@code digest}. */
    public void digestPrefix(MessageDigest digest) {
        long chunkIndex = 0;
        while (true) {
            Chunk chunk = chunks.get(chunkIndex);
            if (chunk == null) {
                return;
            }
            int index = chunk.present.nextSetBit(0);
            if (index != 0) {
                return;
            }
            int end = chunk.present.nextClearBit(0);
            digest.update(chunk.data, 0, end);
            if (end != CHUNK_SIZE) {
                return;
            }
            chunkIndex++;
        }
    }
}
